/* pains.html hook: when a page loads data/radar.js, each hard spot on it gets a link to its practice. Other pages (the mistake book) only use the question data above. */
(function () {
  'use strict';
  function hook() {
    if (document.getElementById('rd-root') || !window.EH_RADAR) return;
    var root = document.body.dataset.root || '';
    window.EH_RADAR.pains.forEach(function (p) {
      var el = document.getElementById(p.id);
      if (!el || !el.classList.contains('trap') || el.querySelector('.rd-hook')) return;
      var a = document.createElement('a');
      a.className = 'chip rd-hook'; a.href = root + window.EH_RADAR.href + '#' + p.id;
      var H = window.EH_RADAR.hook, n = p.q.length;
      a.innerHTML = '🎯 ' + (window.EH ? EH.T(H.en.replace('{n}', n), H.zh.replace('{n}', n)) : H.en.replace('{n}', n));
      (el.querySelector('.chips') || el).appendChild(a);
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', hook); else hook();
})();
